import Foundation

/// Whether a local surface is attached to `stopNoticeEvents` right now. Set
/// by the interactive terminal session; the app socket is asked directly.
enum RetiredNoticeSinks {
    nonisolated(unsafe) static var terminalAttached = false
    /// One notice loop per process (claimed before any suspension).
    nonisolated(unsafe) static var loopActive = false
}

/// The one-time gws / WhatsApp retirement notices (plan v2 §2.6): at most one
/// per retired integration per installation, never generated by the model,
/// never added to history. Independent of `/upgradecheck`.
extension ConversationManager {

    /// Startup pass (before `configure()`): run the migration and fix the
    /// in-memory last channel when it pointed at WhatsApp.
    func applyRetiredIntegrationsMigration() {
        let report = RetiredIntegrations.migrate()
        if let inert = report.inert {
            print("[RetiredIntegrations] state file unreadable (\(inert)); retirement steps paused — see `briglia doctor`")
        }
        if report.stateWriteFailed { print("[RetiredIntegrations] could not write the retirement state; retried at the next start") }
        if let e = report.conversionFailed { print("[RetiredIntegrations] gws settings conversion failed (\(e)); retried at the next start") }
        if let e = report.cleanupFailed { print("[RetiredIntegrations] gws leftover cleanup failed (\(e)); retried at the next start") }
        if let e = report.settingsFailed { print("[RetiredIntegrations] WhatsApp settings cleanup failed (\(e)); retried at the next start") }
        if case .deferred(let why)? = report.folder { print("[RetiredIntegrations] WhatsApp bridge folder kept for now: \(why)") }
        if case .failed(let why)? = report.folder { print("[RetiredIntegrations] WhatsApp bridge folder not fully removed: \(why)") }
        // Routing hygiene, independent of the durable steps' success.
        if lastUserChannelAddress?.kind == .whatsapp {
            lastUserChannelAddress = report.lastUserChannelReplacement
        }
    }

    /// Detached loop; ends when nothing is owed. One tick on start, then
    /// every 60 s while a notice is pending.
    func startRetiredIntegrationsNotices() {
        guard !RetiredNoticeSinks.loopActive,
              case .ok(let state) = RetiredIntegrations.load(RetiredIntegrations.env.stateURL),
              state.gws?.notice == .pending || state.whatsapp?.notice == .pending else { return }
        RetiredNoticeSinks.loopActive = true
        Task { @MainActor [weak self] in
            defer { RetiredNoticeSinks.loopActive = false }
            // Tied to the polling lifetime: a stopped poller sends nothing,
            // and the next startPolling starts a fresh loop.
            while let self, self.isPolling {
                let remaining = await self.retiredNoticeTick()
                guard remaining else { return }
                try? await Task.sleep(nanoseconds: 60_000_000_000)
            }
        }
    }

    /// Returns whether anything is still owed afterwards.
    func retiredNoticeTick(now: Date = Date()) async -> Bool {
        let env = RetiredIntegrations.env
        guard case .ok(let state) = RetiredIntegrations.load(env.stateURL) else { return false }
        let stillOwed = state.gws?.notice == .pending || state.whatsapp?.notice == .pending
        guard stillOwed else { return false }
        let idle = isPolling && activeRunId == nil && activeProcessingTask == nil && !isTurnActive && !browserSettingsMutation
        guard idle, let destination = retiredNoticeDestination() else { return true }
        for which in RetiredIntegrations.dueNotices(state, now: now) {
            let attempt = RetiredIntegrations.Attempt(channelKind: destination.channelKind, chatId: destination.chatId,
                                                      channelGeneration: destination.channelGeneration, at: now)
            guard let text = RetiredIntegrations.consume(which, destination: attempt,
                                                         language: MenuEnvironment.defaultLanguage(), env: env) else { continue }
            let outcome = await sendNoticeOnce(channelKind: destination.channelKind, chatId: destination.chatId,
                                               channelGeneration: destination.channelGeneration, text: text)
            switch outcome {
            case .accepted, .ambiguous:
                RetiredIntegrations.settle(which, .done, env: env)
            case .refused(let after):
                RetiredIntegrations.settle(which, .retry(now.addingTimeInterval(max(after, 60))), env: env)
            case .dropped:
                RetiredIntegrations.settle(which, .retry(now.addingTimeInterval(60)), env: env)
            }
        }
        guard case .ok(let after) = RetiredIntegrations.load(env.stateURL) else { return false }
        return after.gws?.notice == .pending || after.whatsapp?.notice == .pending
    }

    /// Telegram when its channel is registered (the update-notice rule), else
    /// a local surface only while one is attached. nil = not ready yet.
    func retiredNoticeDestination() -> UpdateNotice.Destination? {
        let destination = updateNoticeDestination()
        if let kind = destination.channelKind, kind != ChannelKind.app.rawValue {
            return destination
        }
        guard RetiredNoticeSinks.terminalAttached || AppChatSocketServer.shared.hasConnectedClients else { return nil }
        return UpdateNotice.Destination(channelKind: nil, chatId: nil, channelGeneration: 0)
    }
}
